            $this->alreadyInClearAllReferencesDeep = false;
        } // if ($deep)

        if ($this->collDocDetallePrestamos instanceof PropelCollection) {
            $this->collDocDetallePrestamos->clearIterator();
        }
        $this->collDocDetallePrestamos = null;
        if ($this->collDocPrestamos instanceof PropelCollection) {
